import{_ as t,o as i,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse(`{"title":"La Loi de l'Auto-Croissance et de l'Auto-Développement","description":"","frontmatter":{},"headers":[],"relativePath":"fr/07-自生自长进化法则.md","filePath":"fr/07-自生自长进化法则.md","lastUpdated":null}`),s={name:"fr/07-自生自长进化法则.md"};function a(r,e,l,u,d,c){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="la-loi-de-l-auto-croissance-et-de-l-auto-developpement" tabindex="-1">La Loi de l&#39;Auto-Croissance et de l&#39;Auto-Développement <a class="header-anchor" href="#la-loi-de-l-auto-croissance-et-de-l-auto-developpement" aria-label="Permalink to &quot;La Loi de l&#39;Auto-Croissance et de l&#39;Auto-Développement&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>07</td></tr><tr><td>Module</td><td>Principes généraux et paramètres fondamentaux</td></tr><tr><td>Mots-clés</td><td>Auto-croissance, Évolution autonome, Motivation intrinsèque, Respect du rythme, Développement du potentiel</td></tr></tbody></table><h2 id="i-definition-fondamentale-de-l-auto-croissance-et-de-l-auto-developpement" tabindex="-1">I. Définition fondamentale de l&#39;Auto-Croissance et de l&#39;Auto-Développement <a class="header-anchor" href="#i-definition-fondamentale-de-l-auto-croissance-et-de-l-auto-developpement" aria-label="Permalink to &quot;I. Définition fondamentale de l&#39;Auto-Croissance et de l&#39;Auto-Développement&quot;">​</a></h2><p>L&#39;auto-croissance et l&#39;auto-développement est l&#39;une des lois évolutives centrales de la Civilisation Symbiotique de l&#39;Ancre, signifiant que l&#39;évolution de chaque vie doit prendre sa propre volonté autonome intrinsèque et son rythme naturel comme force motrice fondamentale, et que l&#39;environnement externe et les institutions doivent fournir un soutien et des garanties à cette évolution autonome, plutôt que d&#39;intervenir par la force ou de forcer la croissance. « Auto-croissance » souligne que la force motrice de l&#39;évolution vient de la vie elle-même ; « auto-développement » souligne que le rythme de l&#39;évolution suit les propres lois de la vie.</p><p>La loi de l&#39;auto-croissance et de l&#39;auto-développement contraste nettement avec l&#39;« évolution forcée » du prédationisme. Le prédationisme obtient souvent une évolution rapide mais déformée en dévorant l&#39;Origine des autres, par l&#39;infusion forcée d&#39;énergie, le contrôle de l&#39;âme et d&#39;autres moyens. Bien que cette évolution puisse élever le niveau à court terme, à long terme elle détruit la fondation évolutive de la vie elle-même, conduisant à une Origine impure, des niveaux instables et des esprits endommagés. La loi de l&#39;auto-croissance et de l&#39;auto-développement insiste sur le fait qu&#39;une évolution véritablement solide doit être cultivée de l&#39;intérieur de la vie elle-même, de l&#39;intérieur vers l&#39;extérieur.</p><h2 id="ii-fondement-theorique-de-l-auto-croissance-et-de-l-auto-developpement" tabindex="-1">II. Fondement théorique de l&#39;Auto-Croissance et de l&#39;Auto-Développement <a class="header-anchor" href="#ii-fondement-theorique-de-l-auto-croissance-et-de-l-auto-developpement" aria-label="Permalink to &quot;II. Fondement théorique de l&#39;Auto-Croissance et de l&#39;Auto-Développement&quot;">​</a></h2><p>L&#39;établissement de la loi de l&#39;auto-croissance et de l&#39;auto-développement repose sur une compréhension profonde des lois de l&#39;évolution de la vie :</p><h3 id="_2-1-l-autonomie-de-la-vie-est-la-force-motrice-fondamentale-de-l-evolution" tabindex="-1">2.1 L&#39;autonomie de la vie est la force motrice fondamentale de l&#39;évolution <a class="header-anchor" href="#_2-1-l-autonomie-de-la-vie-est-la-force-motrice-fondamentale-de-l-evolution" aria-label="Permalink to &quot;2.1 L&#39;autonomie de la vie est la force motrice fondamentale de l&#39;évolution&quot;">​</a></h3><p>Chaque vie possède une volonté et un potentiel évolutifs intrinsèques, et cette autonomie est la force motrice la plus fondamentale et la plus durable de l&#39;évolution. Les incitations et le soutien externes peuvent éveiller cette autonomie, mais ne peuvent pas la remplacer. Lorsqu&#39;une vie pratique par son propre désir et choix, la concentration, la créativité et l&#39;endurance de sa culture sont bien supérieures à celles des cas de pratique forcée ou induite.</p><h3 id="_2-2-chaque-vie-a-un-rythme-evolutif-unique" tabindex="-1">2.2 Chaque vie a un rythme évolutif unique <a class="header-anchor" href="#_2-2-chaque-vie-a-un-rythme-evolutif-unique" aria-label="Permalink to &quot;2.2 Chaque vie a un rythme évolutif unique&quot;">​</a></h3><p>Les différentes vies ont des rythmes évolutifs différents en raison des différences de traits raciaux, de dons individuels, d&#39;environnements de croissance et de maturité mentale. Certaines vies conviennent aux percées rapides ; certaines nécessitent une accumulation lente ; certaines peuvent atteindre de hauts niveaux à un jeune âge ; certaines s&#39;épanouissent tardivement. La loi de l&#39;auto-croissance et de l&#39;auto-développement respecte cette différence et n&#39;exige pas que toutes les vies évoluent selon un calendrier unifié.</p><h3 id="_2-3-l-intervention-forcee-detruit-la-fondation-naturelle-de-l-evolution" tabindex="-1">2.3 L&#39;intervention forcée détruit la fondation naturelle de l&#39;évolution <a class="header-anchor" href="#_2-3-l-intervention-forcee-detruit-la-fondation-naturelle-de-l-evolution" aria-label="Permalink to &quot;2.3 L&#39;intervention forcée détruit la fondation naturelle de l&#39;évolution&quot;">​</a></h3><p>De nombreux cas dans l&#39;histoire de la culture montrent que l&#39;« évolution rapide » obtenue par l&#39;infusion forcée d&#39;énergie, la transplantation d&#39;Origine, le contrôle de l&#39;âme et d&#39;autres moyens est souvent accompagnée de graves séquelles : niveaux flottants irréels, Origines impures, démons intérieurs proliférants, durées de vie raccourcies et même déviation de la culture. Cela s&#39;explique par le fait que la puissance imposée de l&#39;extérieur ne s&#39;est pas pleinement fusionnée avec l&#39;Origine de la vie elle-même, produisant un effet de « rejet de corps étranger ». Bien que l&#39;évolution auto-croissante puisse être plus lente, chaque étape est solide et stable, avec une fondation profonde.</p><h2 id="iii-principes-pratiques-de-l-auto-croissance-et-de-l-auto-developpement" tabindex="-1">III. Principes pratiques de l&#39;Auto-Croissance et de l&#39;Auto-Développement <a class="header-anchor" href="#iii-principes-pratiques-de-l-auto-croissance-et-de-l-auto-developpement" aria-label="Permalink to &quot;III. Principes pratiques de l&#39;Auto-Croissance et de l&#39;Auto-Développement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Principe</th><th>Signification</th><th>Exigences pratiques</th></tr></thead><tbody><tr><td>Principe du choix autonome</td><td>Les cultivateurs ont le droit de choisir indépendamment leur système de culture, leur voie évolutive et leur rythme de culture</td><td>Ne pas forcer les cultivateurs à choisir des systèmes spécifiques ; ne pas fixer de calendriers de percée unifiés</td></tr><tr><td>Principe de la motivation intrinsèque</td><td>La force motrice de la culture doit venir du désir et de l&#39;intérêt propres du cultivateur</td><td>L&#39;éducation et l&#39;orientation visent à éveiller l&#39;intérêt intrinsèque, non à punir ou à soudoyer</td></tr><tr><td>Principe du respect du rythme</td><td>Respecter le rythme évolutif unique de chaque cultivateur</td><td>Ne pas discriminer ni abandonner les cultivateurs lents ; fournir des plans de soutien personnalisés</td></tr><tr><td>Principe de la priorité à la fondation</td><td>La solidité de l&#39;évolution prime sur la vitesse</td><td>Encourager les cultivateurs à bâtir des fondations solides ; ne pas encourager le sacrifice des fondations pour des percées rapides</td></tr><tr><td>Principe de tolérance à l&#39;erreur</td><td>Permettre aux cultivateurs de faire des erreurs et de prendre des détours pendant l&#39;évolution</td><td>Établir des mécanismes de tolérance à l&#39;erreur ; offrir aux cultivateurs des opportunités de correction et d&#39;ajustement</td></tr><tr><td>Principe de l&#39;auto-réalisation</td><td>Le but ultime de l&#39;évolution est l&#39;auto-réalisation de la vie, non les normes externes</td><td>Ne pas traiter la hauteur du niveau comme critère unique de réussite évolutive</td></tr></tbody></table><h2 id="iv-relation-entre-l-auto-croissance-et-le-soutien-externe" tabindex="-1">IV. Relation entre l&#39;Auto-Croissance et le Soutien Externe <a class="header-anchor" href="#iv-relation-entre-l-auto-croissance-et-le-soutien-externe" aria-label="Permalink to &quot;IV. Relation entre l&#39;Auto-Croissance et le Soutien Externe&quot;">​</a></h2><p>L&#39;auto-croissance et l&#39;auto-développement ne signifie pas « s&#39;allumer et s&#39;éteindre soi-même » ni « laisser-faire ». Au contraire, l&#39;auto-croissance nécessite un bon environnement externe et un soutien institutionnel pour être pleinement réalisée. La civilisation symbiotique fournit les systèmes de soutien suivants à l&#39;auto-croissance :</p><h3 id="_4-1-soutien-informationnel" tabindex="-1">4.1 Soutien informationnel <a class="header-anchor" href="#_4-1-soutien-informationnel" aria-label="Permalink to &quot;4.1 Soutien informationnel&quot;">​</a></h3><p>L&#39;ouverture complète des Trois Cents Systèmes de Culture de l&#39;Origine offre à chaque cultivateur une ample marge de choix. Les cultivateurs peuvent trouver la voie la plus adaptée dans la riche bibliothèque de systèmes selon leurs propres traits. La civilisation symbiotique a également établi un « Mécanisme d&#39;évaluation de compatibilité des systèmes », fournissant des suggestions personnalisées de choix de systèmes aux cultivateurs via le réseau d&#39;ancres, mais le choix final reste toujours entre les mains du cultivateur.</p><h3 id="_4-2-soutien-en-ressources" tabindex="-1">4.2 Soutien en ressources <a class="header-anchor" href="#_4-2-soutien-en-ressources" aria-label="Permalink to &quot;4.2 Soutien en ressources&quot;">​</a></h3><p>Le Système de Contrat Lié à la Production et le système de garantie de base assurent que chaque cultivateur puisse obtenir des ressources de culture de base. Pour les cultivateurs ayant des besoins particuliers (tels que des besoins en ressources spéciales causés par des traits raciaux), la civilisation symbiotique fournit une allocation ciblée de ressources. Le but du soutien en ressources est d&#39;éliminer les soucis des cultivateurs, leur permettant de se concentrer sur leur propre rythme évolutif.</p><h3 id="_4-3-soutien-des-mentors" tabindex="-1">4.3 Soutien des mentors <a class="header-anchor" href="#_4-3-soutien-des-mentors" aria-label="Permalink to &quot;4.3 Soutien des mentors&quot;">​</a></h3><p>Le réseau de mentors interracial fournit aux cultivateurs des conseils et des réponses aux questions. Le rôle du mentor est celui d&#39;un « guide » plutôt que d&#39;un « contrôleur » ; les mentors peuvent partager leur expérience, signaler des problèmes et fournir des suggestions, mais ne peuvent pas forcer les cultivateurs à pratiquer à leur manière. Le système de mentorat met l&#39;accent sur « l&#39;enseignement heuristique », éveillant la capacité de pensée autonome des cultivateurs.</p><h3 id="_4-4-soutien-environnemental" tabindex="-1">4.4 Soutien environnemental <a class="header-anchor" href="#_4-4-soutien-environnemental" aria-label="Permalink to &quot;4.4 Soutien environnemental&quot;">​</a></h3><p>La civilisation symbiotique s&#39;engage à créer un environnement de culture qui encourage l&#39;exploration, tolère les différences et respecte les choix. Les cultivateurs peuvent librement essayer différentes méthodes de culture sans craindre la discrimination pour avoir pris des voies « non conventionnelles ». La civilisation a également établi un « Mécanisme de récompense pour l&#39;innovation en culture », encourageant les cultivateurs à innover et à personnaliser les systèmes existants.</p><h2 id="v-traitement-des-circonstances-particulieres" tabindex="-1">V. Traitement des circonstances particulières <a class="header-anchor" href="#v-traitement-des-circonstances-particulieres" aria-label="Permalink to &quot;V. Traitement des circonstances particulières&quot;">​</a></h2><p>La loi de l&#39;auto-croissance et de l&#39;auto-développement s&#39;applique généralement de manière universelle, mais nécessite un traitement particulier dans les circonstances suivantes :</p><ul><li><strong>Cultivateurs mineurs</strong> : pour les mineurs ne possédant pas encore un jugement autonome complet, leurs tuteurs ou institutions éducatives raciales fournissent des arrangements de culture directifs, mais leurs droits de choix autonomes doivent être progressivement élargis à mesure que leurs esprits mûrissent</li><li><strong>Personnes à l&#39;esprit endommagé</strong> : pour les individus dont l&#39;esprit est endommagé pour diverses raisons et qui ne peuvent temporairement pas cultiver de manière autonome, la civilisation symbiotique fournit un soutien de traitement et de réadaptation, et ils suivent le principe d&#39;auto-croissance après avoir récupéré leurs capacités autonomes</li><li><strong>Personnes ayant dévié</strong> : pour les individus ayant dévié dans leur culture ou devenus fous, la civilisation symbiotique fournit une intervention forcée et un sauvetage, mais cela relève de l&#39;aide médicale plutôt que de l&#39;intervention évolutive ; le but du sauvetage est de restaurer leur capacité d&#39;évolution autonome</li><li><strong>Personnes à tendances dangereuses</strong> : pour les individus dont la direction de culture viole clairement le principe anti-prédation et peut causer un grave préjudice à eux-mêmes ou à autrui, la civilisation symbiotique a le droit de les restreindre et de les guider, mais doit le faire autant que possible par l&#39;éducation et la communication plutôt que par des moyens forcés</li></ul><h2 id="vi-signification-civilisationnelle-de-l-auto-croissance-et-de-l-auto-developpement" tabindex="-1">VI. Signification civilisationnelle de l&#39;Auto-Croissance et de l&#39;Auto-Développement <a class="header-anchor" href="#vi-signification-civilisationnelle-de-l-auto-croissance-et-de-l-auto-developpement" aria-label="Permalink to &quot;VI. Signification civilisationnelle de l&#39;Auto-Croissance et de l&#39;Auto-Développement&quot;">​</a></h2><p>La loi de l&#39;auto-croissance et de l&#39;auto-développement a une signification profonde pour la civilisation symbiotique :</p><p>Premièrement, elle protège la diversité de l&#39;évolution. Lorsque chaque vie évolue selon son propre rythme et sa propre voie, l&#39;univers produira des formes évolutives riches et colorées, et cette diversité est une ressource importante pour l&#39;ascension globale de l&#39;univers.</p><p>Deuxièmement, elle améliore la qualité de l&#39;évolution. L&#39;évolution auto-croissante a une fondation solide et une Origine pure ; les niveaux des cultivateurs sont plus stables, et leur potentiel de percée vers des niveaux supérieurs est plus grand.</p><p>Troisièmement, elle défend la dignité de la vie. Chaque vie est maître de sa propre évolution, non un outil manipulé par autrui. Cette autonomie est l&#39;expression centrale de la dignité de la vie.</p><p>Quatrièmement, elle éveille la créativité de l&#39;évolution. Lorsque les cultivateurs ne sont plus liés par des normes et des rythmes unifiés, ils sont plus susceptibles d&#39;explorer des voies et des méthodes évolutives entièrement nouvelles, contribuant à l&#39;optimisation continue des Trois Cents Systèmes.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>L&#39;auto-croissance et l&#39;auto-développement est le profond respect de la Civilisation Symbiotique de l&#39;Ancre pour les lois de l&#39;évolution de la vie. Elle nous dit que la véritable évolution n&#39;est pas un résultat imposé par des forces externes, mais la croissance de la vie elle-même de l&#39;intérieur vers l&#39;extérieur. Toutes les conceptions institutionnelles de la civilisation symbiotique existent en fin de compte pour créer un bon environnement dans lequel chaque vie peut croître par elle-même, permettant à chaque vie de devenir son meilleur soi selon son propre rythme.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>08-人人有路保障体系 (Système de garantie « Un Chemin pour Chacun »)</li><li>14-修炼境界统一划分 (Division unifiée des niveaux de culture)</li><li>37-共生教育体系 (Système d&#39;éducation symbiotique)</li></ul>',38)])])}const v=t(s,[["render",a]]);export{m as __pageData,v as default};
